package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Integer
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertEquals(123, NumberUtils.createNumber("123").intValue());

        // Long
        assertTrue(NumberUtils.createNumber("1234567890123") instanceof Long);
        assertEquals(1234567890123L, NumberUtils.createNumber("1234567890123").longValue());

        // BigInteger (Too large for Long)
        String bigIntStr = "123456789012345678901234567890";
        Number bigIntRes = NumberUtils.createNumber(bigIntStr);
        assertTrue(bigIntRes instanceof BigInteger);
        assertEquals(new BigInteger(bigIntStr), bigIntRes);

        // Negative BigInteger
        String negBigIntStr = "-123456789012345678901234567890";
        assertEquals(new BigInteger(negBigIntStr), NumberUtils.createNumber(negBigIntStr));
    }


















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() {
        // Float (with suffix 'f')
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);
        assertEquals(1.23f, NumberUtils.createNumber("1.23f").floatValue(), 0.001f);

        // Double (with suffix 'd')
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
        assertEquals(1.23, NumberUtils.createNumber("1.23d").doubleValue(), 0.001);

        // Long suffix 'l'
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);

        // BigInteger suffix 'L'
        assertTrue(NumberUtils.createNumber("12345678901234567890L") instanceof BigInteger);

        // Default behavior for decimals
        assertTrue(NumberUtils.createNumber("1.23") instanceof Float); // Depending on precision logic
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);
    }
















}

